<template>
	<span>
		<NcAppNavigationItem v-if="!editing"
			:name="!deleted ? board.title : undoText"
			:loading="loading"
			:to="routeTo"
			:undo="deleted"
			:menu-placement="'auto'"
			:force-display-actions="isTouchDevice"
			@click="onNavigate"
			@undo="unDelete">
			<template #icon>
				<NcAppNavigationIconBullet :color="board.color" />
				<BoardCloneModal v-if="cloneModalOpen" :board-title="board.title" @close="onCloseCloneModal" />
				<BoardExportModal v-if="exportModalOpen"
					:board-title="board.title"
					@export="onExportBoard"
					@close="onCloseExportBoard" />
			</template>

			<template #counter>
				<AccountIcon v-if="board.acl?.length > 0" />
			</template>

			<template v-if="!deleted" slot="actions">
				<template v-if="!isDueSubmenuActive">
					<NcActionButton icon="icon-info"
						:close-after-click="true"
						@click="actionDetails">
						{{ t('deck', 'Board details') }}
					</NcActionButton>
					<NcActionButton v-if="canManage && !board.archived"
						icon="icon-rename"
						:close-after-click="true"
						@click="actionEdit">
						{{ t('deck', 'Edit board') }}
					</NcActionButton>
					<NcActionButton v-if="canCreate && !board.archived"
						:close-after-click="true"
						@click="showCloneModal">
						<template #icon>
							<CloneIcon :size="20" decorative />
						</template>
						{{ t('deck', 'Clone board') }}
					</NcActionButton>
					<NcActionButton v-if="canManage && board.archived"
						:close-after-click="true"
						@click="actionUnarchive">
						<template #icon>
							<ArchiveIcon :size="20" decorative />
						</template>
						{{ t('deck', 'Unarchive board') }}
					</NcActionButton>
					<NcActionButton v-else-if="canManage && !board.archived"
						:close-after-click="true"
						@click="actionArchive">
						<template #icon>
							<ArchiveIcon :size="20" decorative />
						</template>
						{{ t('deck', 'Archive board') }}
					</NcActionButton>
					<NcActionButton v-if="canManage && !board.archived"
						icon="icon-download"
						:close-after-click="true"
						@click="actionExport">
						{{ t('deck', 'Export board') }}
					</NcActionButton>
					<NcActionButton v-if="!board.archived && board.acl?.length === 0" :icon="board.settings['notify-due'] === 'off' ? 'icon-sound' : 'icon-sound-off'" @click="board.settings['notify-due'] === 'off' ? updateSetting('notify-due', 'all') : updateSetting('notify-due', 'off')">
						{{ board.settings['notify-due'] === 'off' ? t('deck', 'Turn on due date reminders') : t('deck', 'Turn off due date reminders') }}
					</NcActionButton>
					<NcActionButton :close-after-click="true" @click="toggleDefaultBoard">
						<template #icon>
							<PinOffIcon v-if="isDefaultBoard" :size="20" decorative />
							<PinIcon v-else :size="20" decorative />
						</template>
						{{ isDefaultBoard ? t('deck', 'Remove as default board') : t('deck', 'Set as default board') }}
					</NcActionButton>
				</template>

				<!-- Due date reminder settings -->
				<template v-if="isDueSubmenuActive">
					<NcActionButton :icon="updateDueSetting ? 'icon-loading-small' : 'icon-view-previous'"
						:disabled="updateDueSetting"
						@click="isDueSubmenuActive=false">
						{{ t('deck', 'Due date reminders') }}
					</NcActionButton>

					<NcActionButton name="notification"
						icon="icon-sound"
						:disabled="updateDueSetting"
						:class="{ 'forced-active': board.settings['notify-due'] === 'all' }"
						@click="updateSetting('notify-due', 'all')">
						{{ t('deck', 'All cards') }}
					</NcActionButton>
					<NcActionButton name="notification"
						icon="icon-user"
						:disabled="updateDueSetting"
						:class="{ 'forced-active': board.settings['notify-due'] === 'assigned' }"
						@click="updateSetting('notify-due', 'assigned')">
						{{ t('deck', 'Assigned cards') }}
					</NcActionButton>
					<NcActionButton name="notification"
						icon="icon-sound-off"
						:disabled="updateDueSetting"
						:class="{ 'forced-active': board.settings['notify-due'] === 'off' }"
						@click="updateSetting('notify-due', 'off')">
						{{ t('deck', 'No notifications') }}
					</NcActionButton>
				</template>
				<NcActionButton v-else-if="!board.archived && board.acl?.length > 0"
					:name="t('deck', 'Due date reminders')"
					:icon="dueDateReminderIcon"
					@click="isDueSubmenuActive=true">
					{{ dueDateReminderText }}
				</NcActionButton>

				<NcActionButton v-if="canManage && !isDueSubmenuActive"
					icon="icon-delete"
					:close-after-click="true"
					@click="actionDelete">
					{{ t('deck', 'Delete board') }}
				</NcActionButton>

				<NcActionButton v-if="canLeave && !isDueSubmenuActive"
					icon="icon-delete"
					:close-after-click="true"
					@click="actionLeave">
					<template #icon>
						<LeaveIcon :size="20" decorative />
					</template>
					{{ t('deck', 'Leave board') }}
				</NcActionButton>
			</template>
		</NcAppNavigationItem>
		<div v-else-if="editing" class="board-edit">
			<NcColorPicker v-model="editColor" class="app-navigation-entry-bullet-wrapper">
				<button :style="{ backgroundColor: getColor }" class="color0 icon-colorpicker app-navigation-entry-bullet" />
			</NcColorPicker>
			<form @submit.prevent.stop="applyEdit">
				<NcTextField ref="inputField"
					:disable="loading"
					:value.sync="editTitle"
					:placeholder="t('deck', 'Board name')"
					type="text"
					required />
				<NcButton type="tertiary"
					:disabled="loading"
					native-type="button"
					:title="t('deck', 'Cancel edit')"
					@click.stop.prevent="cancelEdit">
					<template #icon>
						<CloseIcon :size="20" />
					</template>
				</NcButton>
				<NcButton type="tertiary"
					native-type="submit"
					:disabled="loading"
					:title="t('deck', 'Save board')">
					<template #icon>
						<CheckIcon v-if="!loading" :size="20" />
						<NcLoadingIcon v-else :size="20" />
					</template>
				</NcButton>
			</form>
		</div>
	</span>
</template>

<script>
import { NcAppNavigationIconBullet, NcAppNavigationItem, NcColorPicker, NcButton, NcTextField, NcActionButton } from '@nextcloud/vue'
import ClickOutside from 'vue-click-outside'
import ArchiveIcon from 'vue-material-design-icons/ArchiveOutline.vue'
import CloneIcon from 'vue-material-design-icons/ContentDuplicate.vue'
import LeaveIcon from 'vue-material-design-icons/ExitRun.vue'
import AccountIcon from 'vue-material-design-icons/AccountOutline.vue'
import CloseIcon from 'vue-material-design-icons/Close.vue'
import CheckIcon from 'vue-material-design-icons/Check.vue'
import PinIcon from 'vue-material-design-icons/Pin.vue'
import PinOffIcon from 'vue-material-design-icons/PinOff.vue'

import { loadState } from '@nextcloud/initial-state'
import { emit } from '@nextcloud/event-bus'

import isTouchDevice from '../../mixins/isTouchDevice.js'
import BoardCloneModal from './BoardCloneModal.vue'
import BoardExportModal from './BoardExportModal.vue'
import { showLoading, showError } from '@nextcloud/dialogs'
import { getCurrentUser } from '@nextcloud/auth'

const canCreateState = loadState('deck', 'canCreate')

export default {
	name: 'AppNavigationBoard',
	components: {
		NcAppNavigationIconBullet,
		NcAppNavigationItem,
		NcColorPicker,
		NcButton,
		NcTextField,
		NcActionButton,
		AccountIcon,
		ArchiveIcon,
		CloneIcon,
		CloseIcon,
		CheckIcon,
		PinIcon,
		PinOffIcon,
		LeaveIcon,
		BoardCloneModal,
		BoardExportModal,
	},
	directives: {
		ClickOutside,
	},
	mixins: [isTouchDevice],
	inject: [
		'boardApi',
	],
	props: {
		board: {
			type: Object,
			required: true,
		},
	},
	data() {
		return {
			classes: [],
			deleted: false,
			loading: false,
			editing: false,
			menuOpen: false,
			undoTimeoutHandle: null,
			editTitle: '',
			editColor: '',
			isDueSubmenuActive: false,
			updateDueSetting: null,
			canCreate: canCreateState,
			cloneModalOpen: false,
			exportModalOpen: false,
			currentUser: getCurrentUser(),
			defaultBoardId: localStorage.getItem('deck.defaultBoardId'),
		}
	},
	computed: {
		getColor() {
			if (this.editColor !== '') {
				return this.editColor
			}
			return this.board.color
		},
		undoText() {
			return t('deck', 'Board {0} deleted', [this.board.title])
		},
		routeTo() {
			return {
				name: 'board',
				params: { id: this.board.id },
			}
		},
		canManage() {
			return this.board.permissions.PERMISSION_MANAGE
		},
		canLeave() {
			return this.board.acl?.find((acl) => acl.participant.uid === this.currentUser?.uid && acl.participant.type === 0) !== undefined
		},
		dueDateReminderIcon() {
			if (this.board.settings['notify-due'] === 'all') {
				return 'icon-sound'
			} else if (this.board.settings['notify-due'] === 'assigned') {
				return 'icon-user'
			} else if (this.board.settings['notify-due'] === 'off') {
				return 'icon-sound-off'
			}
			return ''
		},
		dueDateReminderText() {
			if (this.board.settings['notify-due'] === 'all') {
				return t('deck', 'All cards')
			} else if (this.board.settings['notify-due'] === 'assigned') {
				return t('deck', 'Only assigned cards')
			} else if (this.board.settings['notify-due'] === 'off') {
				return t('deck', 'No reminder')
			}
			return ''
		},
		isDefaultBoard() {
			return this.defaultBoardId === String(this.board.id)
		},
	},
	watch: {},
	mounted() {
		// prevent click outside event with popupItem.
		this.popupItem = this.$el
	},
	methods: {
		toggleDefaultBoard() {
			if (this.isDefaultBoard) {
				localStorage.removeItem('deck.defaultBoardId')
				this.defaultBoardId = null
			} else {
				localStorage.setItem('deck.defaultBoardId', String(this.board.id))
				this.defaultBoardId = String(this.board.id)
			}
		},
		unDelete() {
			clearTimeout(this.undoTimeoutHandle)
			this.boardApi.unDeleteBoard(this.board)
				.then(() => {
					this.deleted = false
				})
		},
		actionEdit() {
			this.editTitle = this.board.title
			this.editColor = '#' + this.board.color
			this.editing = true
			this.$nextTick(() => {
				this.$refs?.inputField.focus()
			})
		},
		async actionClone() {
			this.loading = true
			try {
				const newBoard = await this.$store.dispatch('cloneBoard', this.board)
				this.loading = false
				if (newBoard instanceof Error) {
					throw newBoard
				}
				this.$router.push({ name: 'board', params: { id: newBoard.id } })
			} catch (e) {
				OC.Notification.showTemporary(t('deck', 'An error occurred'))
				console.error(e)
			}
		},
		actionArchive() {
			this.loading = true
			this.$store.dispatch('archiveBoard', this.board)
		},
		actionUnarchive() {
			this.loading = true
			this.$store.dispatch('unarchiveBoard', this.board)
		},
		actionDelete() {
			OC.dialogs.confirmDestructive(
				t('deck', 'Are you sure you want to delete the board {title}? This will delete all the data of this board including archived cards.', { title: this.board.title }),
				t('deck', 'Delete the board?'),
				{
					type: OC.dialogs.YES_NO_BUTTONS,
					confirm: t('deck', 'Delete'),
					confirmClasses: 'error',
					cancel: t('deck', 'Cancel'),
				},
				(result) => {
					if (result) {
						this.loading = true
						this.boardApi.deleteBoard(this.board)
							.then(() => {
								this.loading = false
								this.deleted = true
								this.redirectToOverviewIfCurrentBoard()
								this.undoTimeoutHandle = setTimeout(() => {
									this.$store.dispatch('removeBoard', this.board)
								}, 7000)
							})
					}
				},
				true,
			)
		},
		actionLeave() {
			OC.dialogs.confirmDestructive(
				t('deck', 'Are you sure you want to leave the board {title}?', { title: this.board.title }),
				t('deck', 'Leave the board?'),
				{
					type: OC.dialogs.YES_NO_BUTTONS,
					confirm: t('deck', 'Leave'),
					confirmClasses: 'error',
					cancel: t('deck', 'Cancel'),
				},
				(result) => {
					if (result) {
						this.loading = true
						this.boardApi.leaveBoard(this.board)
							.then(() => {
								this.loading = false
								this.redirectToOverviewIfCurrentBoard()
								this.$store.dispatch('removeBoard', this.board)
							})
							.catch(() => {
								showError(t('deck', 'Failed to leave the board'))
								this.loading = false
							})
					}
				},
				true,
			)
		},
		actionDetails() {
			this.$router.push({ name: 'board.details', params: { id: this.board.id } })
		},
		applyEdit(e) {
			this.editing = false
			if (this.editTitle || this.editColor) {
				this.loading = true
				const copy = JSON.parse(JSON.stringify(this.board))
				copy.title = this.editTitle
				copy.color = (typeof this.editColor.hex !== 'undefined' ? this.editColor.hex : this.editColor).substring(1)
				this.$store.dispatch('updateBoard', copy)
					.then(() => {
						this.loading = false
					})
			}
		},
		cancelEdit(e) {
			this.editing = false
		},
		async updateSetting(key, value) {
			this.updateDueSetting = value
			const setting = {}
			setting['board:' + this.board.id + ':' + key] = value
			await this.$store.dispatch('setConfig', setting)
			this.isDueSubmenuActive = false
			this.updateDueSetting = null
		},
		actionExport() {
			this.exportModalOpen = true
		},
		async onExportBoard(format) {
			this.exportModalOpen = false
			const loadingToast = showLoading(t('deck', 'Exporting board...'))
			await this.boardApi.exportBoard(this.board, format)
			loadingToast.hideToast()
		},
		onCloseExportBoard() {
			this.exportModalOpen = false
		},
		onNavigate() {
			if (this.isTouchDevice) {
				emit('toggle-navigation', {
					open: false,
				})
			}
		},
		showCloneModal() {
			this.cloneModalOpen = true
		},
		async onCloseCloneModal(data) {
			this.cloneModalOpen = false
			if (data) {
				this.loading = true
				try {
					const newBoard = await this.$store.dispatch('cloneBoard', {
						boardData: this.board,
						settings: data,
					})
					this.loading = false
					this.$router.push({ name: 'board', params: { id: newBoard.id } })
				} catch (e) {
					OC.Notification.showTemporary(t('deck', 'An error occurred'))
					console.error(e)
				}
			}
		},
		redirectToOverviewIfCurrentBoard() {
			const currentBoardId = Number.parseInt(this.$route?.params?.id, 10)
			if (!Number.isNaN(currentBoardId) && currentBoardId === this.board.id) {
				this.$router.push({ name: 'main' })
			}
		},
	},
}
</script>

<style lang="scss" scoped>
	.board-edit {
		margin-inline-start: calc(var(--default-clickable-area) / 2);
		order: 1;
		display: flex;
		height: var(--default-clickable-area);

		form {
			display: flex;
			flex-grow: 1;

			input[type='text'] {
				flex-grow: 1;
			}
		}
	}

	.app-navigation-entry-bullet-wrapper {
		width: var(--default-clickable-area);
		height: var(--default-clickable-area);
		.color0 {
			width: 24px !important;
			height: 24px;
			min-height: 0;
			margin: var(--default-grid-baseline);
			border-radius: 50%;
			background-size: 14px;
		}
	}

	.forced-active {
		box-shadow: inset 4px 0 var(--color-primary-element);
	}

	:deep(.active) {
		.material-design-icon svg {
			fill: var(--color-primary-element-text);
		}
	}
</style>
